if('IntersectionObserver'in window)document.documentElement.classList.add('js');const menuButton=document.querySelector('.menu-toggle');const navigation=document.querySelector('.nav');const scrollTopButton=document.querySelector('.scroll-top');menuButton.addEventListener('click',()=>{const isOpen=navigation.classList.toggle('is-open');menuButton.setAttribute('aria-expanded',String(isOpen));menuButton.setAttribute('aria-label',isOpen?'Close menu':'Open menu');});navigation.querySelectorAll('a').forEach((link)=>link.addEventListener('click',()=>{navigation.classList.remove('is-open');menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Open menu');}));const updateScrollTopButton=()=>scrollTopButton.classList.toggle('is-visible',window.scrollY>320);window.addEventListener('scroll',updateScrollTopButton,{passive:true});scrollTopButton.addEventListener('click',()=>{window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});});updateScrollTopButton();document.querySelector('#year').textContent=new Date().getFullYear();const observer=new IntersectionObserver((entries)=>entries.forEach((entry)=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}}),{threshold:0.12});document.querySelectorAll('.reveal').forEach((element)=>observer.observe(element));